import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"draft":true},"headers":[],"relativePath":"guides/the-manual/reactivity/misc.md","filePath":"guides/the-manual/reactivity/misc.md"}`),a={name:`guides/the-manual/reactivity/misc.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p>In addition to request and cache management, WarpDrive provides a reactive access layer for data in the cache.</p><p>Data in the cache is conceptualized as belonging to one of three forms</p><ul><li><strong>Documents</strong> - the response to a request</li><li><strong>Resources</strong> - a unique cacheable entity within the response to a request</li><li><strong>Fields</strong> - the data for an individual property on a resource</li></ul><p>Each form of data can be accessed and managed reactively through one of two modes</p><ul><li><em>(upcoming, default in v6)</em> <a href="./../schemas/resources/polaris-mode">PolarisMode</a></li><li><em>(current, default in v5)</em> <a href="./../schemas/resources/legacy-mode">LegacyMode</a></li></ul><p>These modes are interoperable. The reactive object (record) for a resource in PolarisMode can relate to a record in LegacyMode and vice-versa. This interoperability is true whether the record in LegacyMode is a ReactiveResource or a Model.</p><p>These reactive primitives use fine-grained signals-based reactivity. The specific implementation used is pluggable and can be integrated with any implementation or even multiple at once.</p><p>For Ember, we use glimmer&#39;s implementation of <code>Signal</code> (<code>@tracked</code>) and <code>Computed</code> (<code>@cached</code>), though the integration does not have to be an implementation of signals at all! For instance, <code>react</code> could be integrated by utilizing <a href="https://react.dev/reference/react/useSyncExternalStore" target="_blank" rel="noreferrer">useSyncExternalStore</a> in place of signals and subscribing to all potential changes via the notification manager.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};